CREATE TABLE IF NOT EXISTS money_ofc_rep (rep_no VARCHAR(30) NOT NULL, tran_id VARCHAR(30) NOT NULL, item_no INT NOT NULL, vn VARCHAR(20) NOT NULL, service_date DATE NULL, adp_code VARCHAR(15) NOT NULL, item_name VARCHAR(255) NOT NULL, qty DECIMAL(12,2) NOT NULL, claim DECIMAL(15,2) NOT NULL, paid DECIMAL(15,2) NOT NULL, deny VARCHAR(10) NOT NULL, error_code VARCHAR(100) NOT NULL, uploaded_at DATETIME NOT NULL, uploaded_by CHAR(36) NOT NULL, PRIMARY KEY (rep_no, tran_id, item_no), KEY money_ofc_rep_vn (vn), KEY money_ofc_rep_date (service_date), CONSTRAINT money_ofc_rep_person_fk FOREIGN KEY (uploaded_by) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS money_ofc_stm (doc_no VARCHAR(40) NOT NULL, rep_no VARCHAR(30) NOT NULL, vn VARCHAR(20) NOT NULL, service_date DATE NULL, claim DECIMAL(15,2) NOT NULL, inst DECIMAL(15,2) NOT NULL, total DECIMAL(15,2) NOT NULL, uploaded_at DATETIME NOT NULL, uploaded_by CHAR(36) NOT NULL, PRIMARY KEY (doc_no, rep_no, vn), KEY money_ofc_stm_vn (vn), CONSTRAINT money_ofc_stm_person_fk FOREIGN KEY (uploaded_by) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
